-- 360_kitchen_cookpool_recipes: the full food list, densities, and Cookpool's own recipes.
--
-- Context: kitchen
-- Epic: cookpool-recipes (RC-7, design §2, §3.3, §5.5, §6) — the food list grows
--       from RC-4's 70 to about 300 everyday foods with their names in
--       English, Hindi and the regional words people use; each food can
--       carry a density, so a spoon of turmeric meets a 100 g pack; and
--       Cookpool's own recipes — about 40 home staples — are written once,
--       here, under the system user usr_cookpool.
--
-- Design rules:
--   * Additive and idempotent: one nullable column on kitchen_foods with no
--     default (SQLite has no ADD COLUMN IF NOT EXISTS, so the runner's
--     applied ledger keeps it from running twice, as 330 and 340 do); every
--     seed row with INSERT OR IGNORE; the densities of RC-4's foods only where
--     still unset; and one backfill UPDATE of items still unlinked. RC-4's
--     foods and names are never changed or removed: 360 only adds names to them.
--   * g_per_ml is grams per millilitre, for foods measured by the spoon or cup
--     and bought by weight (or the other way round): ground spices about
--     0.4–0.6, salt 1.2, sugar 0.85, flours about 0.5, rice 0.8, dals about
--     0.8, oil 0.92, ghee 0.9. The values are household weights per
--     volume (USDA FoodData Central's measures, FAO/INFOODS's density table,
--     common Indian kitchen conversions), rounded. NULL means it has none:
--     the match then never meets a volume with a weight of it (design §3.3).
--   * The match converts through it (kitchen-worker's itemPerLine): a line in
--     ml, L, tsp, tbsp or cup meets an item weighed in g or kg, and the other
--     way round; a count meets either through each_g as before.
--   * A name belongs to one food (kitchen_food_names' primary key) and is
--     stored folded, lower(trim()); every food answers to its own key in words
--     ("toor dal" for toor_dal).
--   * Cookpool's recipes belong to usr_cookpool with is_system = 1, the way
--     RC-4 keeps them: visible to everyone (kitchen-worker's canSee), edited
--     by no one, visibility groups with no link code. Their ids are fixed
--     (c00c0360-…), so a re-run adds nothing and copies keep their source.
--     created_at steps back a minute a recipe, so Explore's newest-first
--     order is the order below.
--   * Every recipe has 3–8 steps of at most 200 characters, serves 2 to 6,
--     and exactly one main line, never to taste; every line names a food on
--     the list, in one of the app's units (g kg ml L pcs tsp tbsp cup), at an
--     amount on its unit's rounding grid, so scaleLine at × 1 is the amount
--     as written. Katori is not one of the units, so lines say cups.
--   * Each seed statement stays well under D1's 100 KB statement limit: one
--     INSERT a group of foods, of names, and of recipes' lines and steps.

ALTER TABLE kitchen_foods ADD COLUMN g_per_ml REAL NULL CHECK (g_per_ml IS NULL OR (g_per_ml > 0 AND g_per_ml <= 5));

-- RC-4's foods measured by the spoon or cup: their densities, only where unset.
UPDATE kitchen_foods SET g_per_ml = CASE key
  WHEN 'onion' THEN 0.65
  WHEN 'tomato' THEN 0.75
  WHEN 'potato' THEN 0.62
  WHEN 'green_peas' THEN 0.6
  WHEN 'carrot' THEN 0.53
  WHEN 'cabbage' THEN 0.29
  WHEN 'spinach' THEN 0.13
  WHEN 'coconut' THEN 0.35
  WHEN 'coriander_leaves' THEN 0.07
  WHEN 'mint' THEN 0.1
  WHEN 'curry_leaves' THEN 0.07
  WHEN 'garlic' THEN 0.55
  WHEN 'ginger' THEN 0.4
  WHEN 'rice' THEN 0.8
  WHEN 'atta' THEN 0.5
  WHEN 'maida' THEN 0.52
  WHEN 'besan' THEN 0.4
  WHEN 'rava' THEN 0.7
  WHEN 'poha' THEN 0.32
  WHEN 'pasta' THEN 0.44
  WHEN 'oats' THEN 0.34
  WHEN 'toor_dal' THEN 0.82
  WHEN 'moong_dal' THEN 0.85
  WHEN 'masoor_dal' THEN 0.8
  WHEN 'chana_dal' THEN 0.82
  WHEN 'urad_dal' THEN 0.85
  WHEN 'chickpeas' THEN 0.83
  WHEN 'rajma' THEN 0.77
  WHEN 'milk' THEN 1.03
  WHEN 'curd' THEN 1.03
  WHEN 'butter' THEN 0.95
  WHEN 'ghee' THEN 0.9
  WHEN 'cream' THEN 1
  WHEN 'cheese' THEN 0.45
  WHEN 'oil' THEN 0.92
  WHEN 'salt' THEN 1.2
  WHEN 'sugar' THEN 0.85
  WHEN 'jaggery' THEN 0.7
  WHEN 'water' THEN 1
  WHEN 'tea' THEN 0.5
  WHEN 'turmeric' THEN 0.6
  WHEN 'red_chilli_powder' THEN 0.54
  WHEN 'coriander_powder' THEN 0.45
  WHEN 'cumin' THEN 0.42
  WHEN 'mustard_seeds' THEN 0.66
  WHEN 'garam_masala' THEN 0.5
  WHEN 'ginger_garlic_paste' THEN 1.1
  WHEN 'black_pepper' THEN 0.46
  WHEN 'cardamom' THEN 0.4
  WHEN 'hing' THEN 0.6
END
WHERE g_per_ml IS NULL AND key IN ('onion', 'tomato', 'potato', 'green_peas', 'carrot', 'cabbage', 'spinach', 'coconut', 'coriander_leaves', 'mint', 'curry_leaves', 'garlic', 'ginger', 'rice', 'atta', 'maida', 'besan', 'rava', 'poha', 'pasta', 'oats', 'toor_dal', 'moong_dal', 'masoor_dal', 'chana_dal', 'urad_dal', 'chickpeas', 'rajma', 'milk', 'curd', 'butter', 'ghee', 'cream', 'cheese', 'oil', 'salt', 'sugar', 'jaggery', 'water', 'tea', 'turmeric', 'red_chilli_powder', 'coriander_powder', 'cumin', 'mustard_seeds', 'garam_masala', 'ginger_garlic_paste', 'black_pepper', 'cardamom', 'hing');

