-- Their steps, 1 of 3: (recipe, position, text).
INSERT OR IGNORE INTO kitchen_recipe_steps (recipe_id, position, text) VALUES
  ('c00c0360-0000-4000-8000-000000000001', 0, 'Rinse the poha in a sieve under running water for a few seconds, drain, and leave it 5 minutes to soften.'),
  ('c00c0360-0000-4000-8000-000000000001', 1, 'Toss the poha with the turmeric, sugar and salt.'),
  ('c00c0360-0000-4000-8000-000000000001', 2, 'Heat the oil and fry the peanuts until golden, then lift them out. Add the mustard seeds, and when they pop, the cumin, curry leaves and chillies.'),
  ('c00c0360-0000-4000-8000-000000000001', 3, 'Add the onion and cook until soft and pale gold, about 3 minutes.'),
  ('c00c0360-0000-4000-8000-000000000001', 4, 'Add the poha and the peanuts, mix gently, cover and steam on low heat for 2 to 3 minutes.'),
  ('c00c0360-0000-4000-8000-000000000001', 5, 'Squeeze over the lemon, scatter the coriander and serve hot.'),
  ('c00c0360-0000-4000-8000-000000000002', 0, 'Dry-roast the rava on low heat, stirring, until it smells toasty but is still pale, about 5 minutes. Tip it onto a plate.'),
  ('c00c0360-0000-4000-8000-000000000002', 1, 'Heat the oil and add the mustard seeds. When they pop, add the urad dal, chana dal and cashews and fry until golden.'),
  ('c00c0360-0000-4000-8000-000000000002', 2, 'Add the curry leaves, chillies, ginger and onion and cook until the onion is soft.'),
  ('c00c0360-0000-4000-8000-000000000002', 3, 'Pour in the water with the salt and bring it to a rolling boil.'),
  ('c00c0360-0000-4000-8000-000000000002', 4, 'Lower the heat and pour in the rava in a thin stream, stirring all the time so no lumps form.'),
  ('c00c0360-0000-4000-8000-000000000002', 5, 'Cover and cook on low for 2 to 3 minutes until the water is absorbed. Fluff it up, add the coriander and serve.'),
  ('c00c0360-0000-4000-8000-000000000003', 0, 'Beat the eggs with a pinch of salt.'),
  ('c00c0360-0000-4000-8000-000000000003', 1, 'Melt the butter in a pan, add the onion and chilli and cook until soft.'),
  ('c00c0360-0000-4000-8000-000000000003', 2, 'Add the tomato, turmeric and chilli powder and cook until the tomato breaks down, 2 to 3 minutes.'),
  ('c00c0360-0000-4000-8000-000000000003', 3, 'Pour in the eggs and stir slowly on low heat until they are just set in soft curds.'),
  ('c00c0360-0000-4000-8000-000000000003', 4, 'Sprinkle over the garam masala and coriander, check the salt and serve with pav or toast.'),
  ('c00c0360-0000-4000-8000-000000000004', 0, 'Whisk the eggs with the salt, pepper and chilli powder until frothy.'),
  ('c00c0360-0000-4000-8000-000000000004', 1, 'Stir in the onion, tomato, chilli and coriander.'),
  ('c00c0360-0000-4000-8000-000000000004', 2, 'Heat half the oil in a frying pan, pour in half the eggs and swirl to spread them.'),
  ('c00c0360-0000-4000-8000-000000000004', 3, 'Cook on medium-low heat until the edges set, then flip and cook 30 seconds more.'),
  ('c00c0360-0000-4000-8000-000000000004', 4, 'Make the second omelette the same way and serve hot with toast.'),
  ('c00c0360-0000-4000-8000-000000000005', 0, 'Rinse the sabudana two or three times, then soak it in the water for 5 to 6 hours or overnight, until each pearl is soft when pressed.'),
  ('c00c0360-0000-4000-8000-000000000005', 1, 'Dry-roast the peanuts, rub off the skins and crush them coarsely. Mix them into the sabudana with the salt and sugar.'),
  ('c00c0360-0000-4000-8000-000000000005', 2, 'Heat the ghee and add the cumin, chillies and curry leaves, then the potato. Cover and cook until the potato is tender.'),
  ('c00c0360-0000-4000-8000-000000000005', 3, 'Add the sabudana and toss on low heat for 5 to 7 minutes, until the pearls turn see-through. Too long and they turn sticky.'),
  ('c00c0360-0000-4000-8000-000000000005', 4, 'Squeeze over the lemon, add the coriander and serve hot.'),
  ('c00c0360-0000-4000-8000-000000000006', 0, 'Knead the atta with the ajwain, a pinch of salt and the water into a soft dough. Cover and rest it for 20 minutes.'),
  ('c00c0360-0000-4000-8000-000000000006', 1, 'Peel and mash the potatoes. Mix in the chillies, coriander, amchur, chilli powder, garam masala and salt.'),
  ('c00c0360-0000-4000-8000-000000000006', 2, 'Divide the dough and the filling into 8 each. Roll a ball of dough into a small disc, set a ball of filling in the middle and pinch it closed.'),
  ('c00c0360-0000-4000-8000-000000000006', 3, 'Dust it with flour and roll it gently into a 6-inch paratha, taking care the filling does not burst out.'),
  ('c00c0360-0000-4000-8000-000000000006', 4, 'Cook on a hot tawa until spotted underneath, flip, brush with ghee and cook both sides until golden.'),
  ('c00c0360-0000-4000-8000-000000000006', 5, 'Serve hot with curd, pickle or a little butter.'),
  ('c00c0360-0000-4000-8000-000000000007', 0, 'Knead the atta, salt, water and 1 tsp of the ghee into a soft dough. Cover and rest it for 15 minutes.'),
  ('c00c0360-0000-4000-8000-000000000007', 1, 'Divide it into 6 balls. Roll one into a disc, brush it with ghee and dust it with flour.'),
  ('c00c0360-0000-4000-8000-000000000007', 2, 'Fold it in half and in half again into a triangle, then roll it out again.'),
  ('c00c0360-0000-4000-8000-000000000007', 3, 'Cook on a hot tawa until bubbles appear, flip, brush with ghee and press with a spatula until both sides are golden and flaky.'),
  ('c00c0360-0000-4000-8000-000000000007', 4, 'Keep the parathas warm in a cloth while you cook the rest.'),
  ('c00c0360-0000-4000-8000-000000000008', 0, 'Mix the atta and salt, then add the water a little at a time and knead into a soft, smooth dough. Rub in the oil, cover and rest it for 20 minutes.'),
  ('c00c0360-0000-4000-8000-000000000008', 1, 'Divide it into 12 balls. Dust one with flour and roll it into a thin 6-inch round.'),
  ('c00c0360-0000-4000-8000-000000000008', 2, 'Cook it on a hot tawa until small bubbles form, about 30 seconds, then flip.'),
  ('c00c0360-0000-4000-8000-000000000008', 3, 'When brown spots appear underneath, hold it over an open flame with tongs, or press it with a cloth on the tawa, until it puffs.'),
  ('c00c0360-0000-4000-8000-000000000008', 4, 'Brush with ghee and stack in a cloth-lined box to keep them soft.'),
  ('c00c0360-0000-4000-8000-000000000009', 0, 'Mix the atta, rava, salt and 1 tbsp oil, then add the water little by little and knead into a stiff, smooth dough. Rest it for 15 minutes.'),
  ('c00c0360-0000-4000-8000-000000000009', 1, 'Divide it into 16 small balls and roll each into a 3-inch round, with a drop of oil instead of dry flour.'),
  ('c00c0360-0000-4000-8000-000000000009', 2, 'Heat the oil for frying until a small piece of dough rises at once.'),
  ('c00c0360-0000-4000-8000-000000000009', 3, 'Slide in one puri and press it gently with a slotted spoon so it puffs, then flip and fry until golden.'),
  ('c00c0360-0000-4000-8000-000000000009', 4, 'Drain on paper and serve hot with aloo sabzi, chole or shrikhand.'),
  ('c00c0360-0000-4000-8000-000000000010', 0, 'Rinse the dal and pressure-cook it with the water, turmeric and a little salt for 3 whistles, until soft. Whisk it smooth.'),
  ('c00c0360-0000-4000-8000-000000000010', 1, 'Heat 1 tbsp of the ghee and add half the cumin, then the onion and chilli, and cook until golden. Add the tomato and cook until soft.'),
  ('c00c0360-0000-4000-8000-000000000010', 2, 'Stir in the dal, loosen it with hot water if needed, check the salt and simmer for 5 minutes.'),
  ('c00c0360-0000-4000-8000-000000000010', 3, 'For the tadka, heat the rest of the ghee and add the rest of the cumin, the garlic and the dried chillies. Fry until the garlic is golden.'),
  ('c00c0360-0000-4000-8000-000000000010', 4, 'Take it off the heat, add the hing and chilli powder, and pour it over the dal at once.'),
  ('c00c0360-0000-4000-8000-000000000010', 5, 'Garnish with coriander and serve with rice or roti.'),
  ('c00c0360-0000-4000-8000-000000000011', 0, 'Pressure-cook the rinsed dal with the water and turmeric for 4 to 5 whistles, then whisk it smooth.'),
  ('c00c0360-0000-4000-8000-000000000011', 1, 'Heat the oil and add the cumin. When it sizzles, add the onion and chillies and fry until golden brown.'),
  ('c00c0360-0000-4000-8000-000000000011', 2, 'Add the ginger-garlic paste and fry for a minute, then the tomatoes, chilli powder, coriander powder and salt. Cook until the oil separates.'),
  ('c00c0360-0000-4000-8000-000000000011', 3, 'Pour in the dal with a little hot water, bring it to a boil and simmer for 5 to 7 minutes.'),
  ('c00c0360-0000-4000-8000-000000000011', 4, 'Crush the kasuri methi between your palms over the pot, add the garam masala and butter, and stir.'),
  ('c00c0360-0000-4000-8000-000000000011', 5, 'Garnish with coriander and serve with jeera rice.'),
  ('c00c0360-0000-4000-8000-000000000012', 0, 'Soak the rajma overnight. Drain, then pressure-cook it with the water and a little salt for 6 to 8 whistles until very soft.'),
  ('c00c0360-0000-4000-8000-000000000012', 1, 'Heat the oil and add the cumin and bay leaf, then the onions, and fry until deep golden.'),
  ('c00c0360-0000-4000-8000-000000000012', 2, 'Add the ginger-garlic paste and chilli, then the tomatoes, turmeric, chilli powder and coriander powder. Cook until the masala is thick and oily.'),
  ('c00c0360-0000-4000-8000-000000000012', 3, 'Add the rajma with its cooking water, mash a few beans to thicken it, and simmer for 15 to 20 minutes.'),
  ('c00c0360-0000-4000-8000-000000000012', 4, 'Stir in the garam masala and coriander. Serve with steamed rice.'),
  ('c00c0360-0000-4000-8000-000000000013', 0, 'Soak the chickpeas overnight. Pressure-cook them with the water, salt and the tea in a muslin bag for 6 to 7 whistles, until soft. Discard the tea.'),
  ('c00c0360-0000-4000-8000-000000000013', 1, 'Heat the oil and add the cumin, then the onions, and fry until browned.'),
  ('c00c0360-0000-4000-8000-000000000013', 2, 'Add the ginger-garlic paste and chillies, then the tomatoes, turmeric and chilli powder, and cook until the oil separates.'),
  ('c00c0360-0000-4000-8000-000000000013', 3, 'Add the chole masala and amchur and fry for a minute, then add the chickpeas with their water.'),
  ('c00c0360-0000-4000-8000-000000000013', 4, 'Mash a few chickpeas, simmer for 15 minutes until thick, and garnish with coriander. Serve with bhature, puri or rice.'),
  ('c00c0360-0000-4000-8000-000000000014', 0, 'Pressure-cook the dal with half the water and the turmeric for 4 whistles, then mash it smooth.'),
  ('c00c0360-0000-4000-8000-000000000014', 1, 'Soak the tamarind in a little warm water for 10 minutes, then squeeze out the pulp and strain it.'),
  ('c00c0360-0000-4000-8000-000000000014', 2, 'Boil the drumstick, onions, brinjal and tomato in the rest of the water with salt until just tender, about 10 minutes.'),
  ('c00c0360-0000-4000-8000-000000000014', 3, 'Add the tamarind water, sambar powder and jaggery and simmer for 5 minutes, then stir in the dal and simmer 5 more.'),
  ('c00c0360-0000-4000-8000-000000000014', 4, 'For the tadka, heat the oil and add the mustard seeds. When they pop, add the fenugreek, dried chillies, curry leaves and hing.'),
  ('c00c0360-0000-4000-8000-000000000014', 5, 'Pour the tadka over the sambar, add the coriander and serve with rice, idli or dosa.');

-- Their steps, 2 of 3: (recipe, position, text).
INSERT OR IGNORE INTO kitchen_recipe_steps (recipe_id, position, text) VALUES
  ('c00c0360-0000-4000-8000-000000000015', 0, 'Soak the tamarind in 1 cup of the water, warm, for 10 minutes, then squeeze and strain it.'),
  ('c00c0360-0000-4000-8000-000000000015', 1, 'Crush the garlic, peppercorns and cumin coarsely in a mortar.'),
  ('c00c0360-0000-4000-8000-000000000015', 2, 'Simmer the tomatoes with the tamarind water, turmeric, salt and the crushed mix until the tomatoes are soft, about 8 minutes.'),
  ('c00c0360-0000-4000-8000-000000000015', 3, 'Add the rest of the water and the rasam powder and heat until it froths at the top. Do not let it boil hard.'),
  ('c00c0360-0000-4000-8000-000000000015', 4, 'Heat the ghee, add the mustard seeds, dried chilli, curry leaves and hing, and pour it over the rasam.'),
  ('c00c0360-0000-4000-8000-000000000015', 5, 'Add the coriander, cover for 5 minutes and serve with rice or in a cup as a soup.'),
  ('c00c0360-0000-4000-8000-000000000016', 0, 'Whisk the curd, besan, turmeric and salt until smooth, then whisk in the water.'),
  ('c00c0360-0000-4000-8000-000000000016', 1, 'Pour it into a heavy pot with the ginger and chilli and bring it to a boil, stirring all the time so it does not split.'),
  ('c00c0360-0000-4000-8000-000000000016', 2, 'Lower the heat and simmer, stirring now and then, for 20 to 25 minutes, until it thickens and loses its raw taste.'),
  ('c00c0360-0000-4000-8000-000000000016', 3, 'For the tadka, heat the ghee and add the mustard, cumin and fenugreek seeds, then the dried chillies, curry leaves and hing. Off the heat, add the chilli powder.'),
  ('c00c0360-0000-4000-8000-000000000016', 4, 'Pour the tadka over the kadhi, add the coriander and serve with rice.'),
  ('c00c0360-0000-4000-8000-000000000017', 0, 'Blanch the spinach in boiling water for 2 minutes, then plunge it into cold water. Blend it with the chillies to a smooth puree.'),
  ('c00c0360-0000-4000-8000-000000000017', 1, 'Heat the oil and add the cumin, then the onion, and fry until golden. Add the garlic and ginger and fry for a minute.'),
  ('c00c0360-0000-4000-8000-000000000017', 2, 'Add the tomato and salt and cook until soft.'),
  ('c00c0360-0000-4000-8000-000000000017', 3, 'Stir in the spinach puree with a splash of water and simmer for 3 to 4 minutes.'),
  ('c00c0360-0000-4000-8000-000000000017', 4, 'Add the paneer, garam masala and crushed kasuri methi and simmer for 2 minutes more.'),
  ('c00c0360-0000-4000-8000-000000000017', 5, 'Swirl in the cream and serve with roti or naan.'),
  ('c00c0360-0000-4000-8000-000000000018', 0, 'Crumble the paneer with your fingers.'),
  ('c00c0360-0000-4000-8000-000000000018', 1, 'Heat the oil, add the onion and chilli and cook until soft, then add the ginger-garlic paste for a minute.'),
  ('c00c0360-0000-4000-8000-000000000018', 2, 'Add the tomato, capsicum, turmeric, chilli powder and salt and cook until the tomato is soft.'),
  ('c00c0360-0000-4000-8000-000000000018', 3, 'Add the paneer and garam masala and toss on medium heat for 2 minutes. Cooked longer, paneer turns rubbery.'),
  ('c00c0360-0000-4000-8000-000000000018', 4, 'Finish with the coriander and serve with roti or toast.'),
  ('c00c0360-0000-4000-8000-000000000019', 0, 'Blend the onions, tomatoes and cashews to a smooth paste.'),
  ('c00c0360-0000-4000-8000-000000000019', 1, 'Heat the oil and add the cumin, then the paste and the ginger-garlic paste. Cook on medium heat until thick and the oil separates, about 10 minutes.'),
  ('c00c0360-0000-4000-8000-000000000019', 2, 'Add the turmeric, chilli powder, coriander powder and salt and cook for a minute.'),
  ('c00c0360-0000-4000-8000-000000000019', 3, 'Add the peas and water, cover and simmer until the peas are tender, about 5 minutes.'),
  ('c00c0360-0000-4000-8000-000000000019', 4, 'Add the paneer and garam masala and simmer for 3 minutes. Garnish with coriander.'),
  ('c00c0360-0000-4000-8000-000000000020', 0, 'Cut the cauliflower into florets and the potatoes into cubes. Rinse and drain.'),
  ('c00c0360-0000-4000-8000-000000000020', 1, 'Heat the oil and add the cumin, then the onion, ginger and chilli, and fry until soft.'),
  ('c00c0360-0000-4000-8000-000000000020', 2, 'Add the potatoes, cover and cook on low for 5 minutes.'),
  ('c00c0360-0000-4000-8000-000000000020', 3, 'Add the cauliflower, tomato, turmeric, chilli powder, coriander powder and salt. Toss, cover and cook on low, stirring now and then, until both are tender, 12 to 15 minutes.'),
  ('c00c0360-0000-4000-8000-000000000020', 4, 'Sprinkle over the garam masala, amchur and coriander and cook uncovered for 2 minutes to dry it out.'),
  ('c00c0360-0000-4000-8000-000000000021', 0, 'Wash the bhindi and dry it completely with a cloth, then cut it into 1 cm pieces. Wet bhindi turns slimy.'),
  ('c00c0360-0000-4000-8000-000000000021', 1, 'Heat the oil and add the cumin, then the onion, and fry until it turns translucent.'),
  ('c00c0360-0000-4000-8000-000000000021', 2, 'Add the bhindi and fry on medium heat, uncovered, stirring gently, until it is no longer sticky, 10 to 12 minutes.'),
  ('c00c0360-0000-4000-8000-000000000021', 3, 'Add the turmeric, chilli powder, coriander powder and salt and cook for 3 to 4 minutes more, until crisp at the edges.'),
  ('c00c0360-0000-4000-8000-000000000021', 4, 'Sprinkle over the amchur, toss and serve with roti or dal and rice.'),
  ('c00c0360-0000-4000-8000-000000000022', 0, 'Rub the brinjal with a little oil and roast it over a gas flame, turning, until the skin is charred all over and it is soft inside, 10 to 15 minutes.'),
  ('c00c0360-0000-4000-8000-000000000022', 1, 'Cool it in a bowl, peel off the skin and mash the flesh.'),
  ('c00c0360-0000-4000-8000-000000000022', 2, 'Heat the oil and add the cumin, then the onion, garlic, ginger and chillies, and fry until golden.'),
  ('c00c0360-0000-4000-8000-000000000022', 3, 'Add the tomatoes, turmeric, chilli powder and salt and cook until soft and pulpy.'),
  ('c00c0360-0000-4000-8000-000000000022', 4, 'Add the mashed brinjal and cook for 5 minutes, stirring. Add the garam masala and coriander and serve with roti.'),
  ('c00c0360-0000-4000-8000-000000000023', 0, 'Marinate the chicken with the curd, turmeric, half the chilli powder, half the ginger-garlic paste and salt for at least 30 minutes.'),
  ('c00c0360-0000-4000-8000-000000000023', 1, 'Heat the oil and add the bay leaf, cinnamon and cloves, then the onions. Fry on medium heat until deep golden brown, about 12 minutes.'),
  ('c00c0360-0000-4000-8000-000000000023', 2, 'Add the rest of the ginger-garlic paste and the chillies and fry for a minute. Add the tomatoes, the rest of the chilli powder and the coriander powder and cook until the oil separates.'),
  ('c00c0360-0000-4000-8000-000000000023', 3, 'Add the chicken and sear it on high heat for 5 minutes, stirring.'),
  ('c00c0360-0000-4000-8000-000000000023', 4, 'Add the water, cover and simmer on low until the chicken is cooked through and tender, 20 to 25 minutes.'),
  ('c00c0360-0000-4000-8000-000000000023', 5, 'Stir in the garam masala and coriander. Serve with rice or roti.'),
  ('c00c0360-0000-4000-8000-000000000024', 0, 'Hard-boil the eggs for 10 minutes, cool them in cold water, peel them and make a few shallow slits in each.'),
  ('c00c0360-0000-4000-8000-000000000024', 1, 'Heat 1 tbsp of the oil with a pinch of turmeric and chilli powder and fry the eggs for 2 minutes until lightly golden. Lift them out.'),
  ('c00c0360-0000-4000-8000-000000000024', 2, 'In the rest of the oil, fry the onions until golden, then the ginger-garlic paste and chilli for a minute.'),
  ('c00c0360-0000-4000-8000-000000000024', 3, 'Add the tomatoes, the spices and salt, and cook until the masala is thick and the oil separates.'),
  ('c00c0360-0000-4000-8000-000000000024', 4, 'Add the water, bring it to a boil, add the eggs and simmer for 5 minutes. Finish with the garam masala and coriander.'),
  ('c00c0360-0000-4000-8000-000000000025', 0, 'Rub the fish with half the turmeric and some salt and set it aside for 15 minutes. Soak the tamarind in the warm water and squeeze out the pulp.'),
  ('c00c0360-0000-4000-8000-000000000025', 1, 'Heat the coconut oil and add the mustard and fenugreek seeds, then the curry leaves.'),
  ('c00c0360-0000-4000-8000-000000000025', 2, 'Add the onion, ginger, garlic and chillies and fry until soft. Add the tomato and cook until mushy.'),
  ('c00c0360-0000-4000-8000-000000000025', 3, 'Lower the heat, add the chilli powder, coriander powder and the rest of the turmeric with a splash of water, and cook for 2 minutes.'),
  ('c00c0360-0000-4000-8000-000000000025', 4, 'Add the tamarind water and bring it to a boil, then slide in the fish and simmer gently for 5 minutes.'),
  ('c00c0360-0000-4000-8000-000000000025', 5, 'Pour in the coconut milk and heat through without boiling, 3 to 4 minutes. Swirl the pan rather than stirring so the fish stays whole.'),
  ('c00c0360-0000-4000-8000-000000000026', 0, 'Rinse the rice until the water runs clear and soak it for 20 minutes. Drain.'),
  ('c00c0360-0000-4000-8000-000000000026', 1, 'Heat the ghee, add the cumin and bay leaf, and let the cumin sizzle and turn a shade darker.'),
  ('c00c0360-0000-4000-8000-000000000026', 2, 'Add the rice and stir gently for a minute to coat it in ghee.'),
  ('c00c0360-0000-4000-8000-000000000026', 3, 'Add the water and salt, bring it to a boil, then cover and cook on the lowest heat for 12 minutes.'),
  ('c00c0360-0000-4000-8000-000000000026', 4, 'Turn off the heat and leave it covered for 5 minutes, then fluff it with a fork.'),
  ('c00c0360-0000-4000-8000-000000000027', 0, 'Rinse the rice and soak it for 20 minutes. Chop the vegetables.'),
  ('c00c0360-0000-4000-8000-000000000027', 1, 'Heat the ghee, add the cumin and the whole spices and let them sizzle. Add the onion and chillies and fry until light golden.'),
  ('c00c0360-0000-4000-8000-000000000027', 2, 'Add the ginger-garlic paste, then the vegetables, and saute for 3 minutes.'),
  ('c00c0360-0000-4000-8000-000000000027', 3, 'Add the drained rice, garam masala and salt and stir gently for a minute.'),
  ('c00c0360-0000-4000-8000-000000000027', 4, 'Pour in the water, bring it to a boil, cover and cook on low for 12 to 15 minutes, or 2 whistles in a pressure cooker.'),
  ('c00c0360-0000-4000-8000-000000000027', 5, 'Rest it for 5 minutes, fluff it up and garnish with coriander. Serve with raita.'),
  ('c00c0360-0000-4000-8000-000000000028', 0, 'Cook the rice in the water until done but separate, then spread it on a plate to cool.'),
  ('c00c0360-0000-4000-8000-000000000028', 1, 'Heat the oil and fry the peanuts until crunchy. Add the mustard seeds, and when they pop, the chana dal and urad dal. Fry until golden.'),
  ('c00c0360-0000-4000-8000-000000000028', 2, 'Add the dried chillies, green chillies, curry leaves and hing, then the turmeric, and take the pan off the heat.'),
  ('c00c0360-0000-4000-8000-000000000028', 3, 'Add the rice and salt and mix gently so the grains stay whole.'),
  ('c00c0360-0000-4000-8000-000000000028', 4, 'Squeeze in the lemon, add the coriander and mix again. Serve warm or at room temperature.');

-- Their steps, 3 of 3: (recipe, position, text).
INSERT OR IGNORE INTO kitchen_recipe_steps (recipe_id, position, text) VALUES
  ('c00c0360-0000-4000-8000-000000000029', 0, 'Cook the rice in the water until very soft, then mash it lightly and let it cool to room temperature.'),
  ('c00c0360-0000-4000-8000-000000000029', 1, 'Mix in the curd, milk and salt until creamy. Add a little more milk if it is thick.'),
  ('c00c0360-0000-4000-8000-000000000029', 2, 'Heat the oil and add the mustard seeds. When they pop, add the urad dal, ginger, chilli, curry leaves and hing, and fry until the dal is golden.'),
  ('c00c0360-0000-4000-8000-000000000029', 3, 'Pour the tempering over the rice, add the coriander and mix. Serve cool with pickle.'),
  ('c00c0360-0000-4000-8000-000000000030', 0, 'Rinse the rice and dal together and soak them for 15 minutes.'),
  ('c00c0360-0000-4000-8000-000000000030', 1, 'Heat the ghee in a pressure cooker and add the cumin. When it sizzles, add the hing, ginger and chilli.'),
  ('c00c0360-0000-4000-8000-000000000030', 2, 'Add the drained rice and dal, the turmeric and salt, and stir for a minute.'),
  ('c00c0360-0000-4000-8000-000000000030', 3, 'Add the water and pressure-cook for 4 to 5 whistles, until soft and like porridge.'),
  ('c00c0360-0000-4000-8000-000000000030', 4, 'Stir well, loosen it with hot water if needed, and serve with a spoon of ghee, curd and papad.'),
  ('c00c0360-0000-4000-8000-000000000031', 0, 'Cook the rice in the water until just done, spread it out and cool it completely, ideally in the fridge.'),
  ('c00c0360-0000-4000-8000-000000000031', 1, 'Chop the vegetables finely and the spring onions, keeping the greens apart.'),
  ('c00c0360-0000-4000-8000-000000000031', 2, 'Heat the oil in a wok until smoking, add the garlic and the spring onion whites and stir-fry for 30 seconds.'),
  ('c00c0360-0000-4000-8000-000000000031', 3, 'Add the carrot, beans, cabbage and capsicum and toss on high heat for 2 to 3 minutes, so they stay crunchy.'),
  ('c00c0360-0000-4000-8000-000000000031', 4, 'Add the rice, soy sauce, vinegar, pepper and salt and toss on high heat until hot and well mixed.'),
  ('c00c0360-0000-4000-8000-000000000031', 5, 'Scatter over the spring onion greens and serve.'),
  ('c00c0360-0000-4000-8000-000000000032', 0, 'Bring the water to a boil with the ginger and cardamom and simmer for 1 minute.'),
  ('c00c0360-0000-4000-8000-000000000032', 1, 'Add the tea leaves and boil for 1 minute, until the water is dark.'),
  ('c00c0360-0000-4000-8000-000000000032', 2, 'Add the milk and sugar and bring it to a boil. Let it rise, lower the heat and simmer for 2 minutes, until the chai turns a deep tan.'),
  ('c00c0360-0000-4000-8000-000000000032', 3, 'Strain into cups and serve hot.'),
  ('c00c0360-0000-4000-8000-000000000033', 0, 'Put the coffee powder in the upper cup of the filter, press it lightly and pour in the boiling water. Cover and leave it 10 to 15 minutes for the decoction to drip.'),
  ('c00c0360-0000-4000-8000-000000000033', 1, 'Bring the milk to a boil.'),
  ('c00c0360-0000-4000-8000-000000000033', 2, 'For each cup, mix about 3 tbsp of decoction with a teaspoon of sugar, then pour in the hot milk.'),
  ('c00c0360-0000-4000-8000-000000000033', 3, 'Pour it between a tumbler and a dabara a few times to froth it, and serve at once.'),
  ('c00c0360-0000-4000-8000-000000000034', 0, 'Put the curd, milk and sugar in a deep jug or a blender.'),
  ('c00c0360-0000-4000-8000-000000000034', 1, 'Whisk or blend for a minute, until frothy and the sugar dissolves.'),
  ('c00c0360-0000-4000-8000-000000000034', 2, 'Add the cardamom and blend again briefly.'),
  ('c00c0360-0000-4000-8000-000000000034', 3, 'Pour into glasses over ice and serve chilled, with a spoon of malai on top if you like.'),
  ('c00c0360-0000-4000-8000-000000000035', 0, 'Squeeze the lemon into a jug and stir in the sugar, black salt and cumin until the sugar dissolves.'),
  ('c00c0360-0000-4000-8000-000000000035', 1, 'Add the cold water and stir well. Taste, and adjust the sugar or lemon.'),
  ('c00c0360-0000-4000-8000-000000000035', 2, 'Pour over ice, add a few torn mint leaves and serve.'),
  ('c00c0360-0000-4000-8000-000000000036', 0, 'Sprinkle the sliced onions with the salt, rub them and leave them for 10 minutes so they release water.'),
  ('c00c0360-0000-4000-8000-000000000036', 1, 'Add the chillies, curry leaves, coriander, ajwain, chilli powder and hing, then the besan and rice flour. Mix with your hands, with only a sprinkle of water, until the onions are coated.'),
  ('c00c0360-0000-4000-8000-000000000036', 2, 'Heat the oil for deep frying on medium-high. A drop of batter should rise quickly.'),
  ('c00c0360-0000-4000-8000-000000000036', 3, 'Drop in small loose clusters and fry, turning, until golden brown and crisp, 4 to 5 minutes.'),
  ('c00c0360-0000-4000-8000-000000000036', 4, 'Drain on paper and serve hot with chai and green chutney.'),
  ('c00c0360-0000-4000-8000-000000000037', 0, 'Pressure-cook the potatoes, cauliflower and peas until very soft, then mash them.'),
  ('c00c0360-0000-4000-8000-000000000037', 1, 'Melt half the butter in a wide pan and cook two of the onions until soft, then add the ginger-garlic paste and capsicum for 2 minutes.'),
  ('c00c0360-0000-4000-8000-000000000037', 2, 'Add the tomatoes and cook, mashing, until they break down completely.'),
  ('c00c0360-0000-4000-8000-000000000037', 3, 'Add the turmeric, chilli powder, pav bhaji masala and salt, then the mashed vegetables and the water. Mash it all together and simmer for 10 minutes.'),
  ('c00c0360-0000-4000-8000-000000000037', 4, 'Finish with a spoon of butter, the coriander and a squeeze of lemon.'),
  ('c00c0360-0000-4000-8000-000000000037', 5, 'Slit the pav, toast them in the rest of the butter on a tawa, and serve with the bhaji, the last onion chopped, and lemon wedges.'),
  ('c00c0360-0000-4000-8000-000000000038', 0, 'Slice the potato, cucumber, tomato and onion into thin rounds.'),
  ('c00c0360-0000-4000-8000-000000000038', 1, 'Butter the bread slices on one side.'),
  ('c00c0360-0000-4000-8000-000000000038', 2, 'Layer two slices with potato, cucumber, onion and tomato, sprinkling chaat masala, pepper and salt over each layer.'),
  ('c00c0360-0000-4000-8000-000000000038', 3, 'Close with the other slices, buttered side in, press lightly and cut in half. Toast them on a tawa or in a sandwich maker if you like.'),
  ('c00c0360-0000-4000-8000-000000000039', 0, 'Warm the milk and water with the sugar until the sugar dissolves. Keep it hot.'),
  ('c00c0360-0000-4000-8000-000000000039', 1, 'Heat the ghee and fry the cashews and raisins until golden, then lift them out.'),
  ('c00c0360-0000-4000-8000-000000000039', 2, 'Add the rava to the ghee and roast it on low heat, stirring, until it smells nutty and turns light golden, 6 to 8 minutes.'),
  ('c00c0360-0000-4000-8000-000000000039', 3, 'Carefully pour in the hot milk, stirring hard, as it will splutter.'),
  ('c00c0360-0000-4000-8000-000000000039', 4, 'Stir until the rava soaks up the liquid and leaves the sides of the pan, 2 to 3 minutes. Add the cardamom, saffron and nuts and serve warm.'),
  ('c00c0360-0000-4000-8000-000000000040', 0, 'Rinse the rice and soak it for 20 minutes.'),
  ('c00c0360-0000-4000-8000-000000000040', 1, 'Bring the milk to a boil in a heavy pan, add the drained rice and simmer on low, stirring often so it does not catch, for 30 to 35 minutes, until the rice is soft and the milk thickens.'),
  ('c00c0360-0000-4000-8000-000000000040', 2, 'Add the sugar and simmer for 5 minutes more.'),
  ('c00c0360-0000-4000-8000-000000000040', 3, 'Stir in the cardamom, saffron and nuts. Serve warm or chilled.'),
  ('c00c0360-0000-4000-8000-000000000041', 0, 'Melt the ghee in a heavy pan, add the besan and roast it on low heat, stirring all the time, for 20 to 25 minutes, until golden and nutty.'),
  ('c00c0360-0000-4000-8000-000000000041', 1, 'Take the pan off the heat and let it cool until just warm to the touch.'),
  ('c00c0360-0000-4000-8000-000000000041', 2, 'Mix in the powdered sugar, cardamom and cashews.'),
  ('c00c0360-0000-4000-8000-000000000041', 3, 'Take a small handful and press it into a tight ball between your palms. It makes about 12.'),
  ('c00c0360-0000-4000-8000-000000000041', 4, 'Cool them fully and keep them in an airtight box for up to two weeks.'),
  ('c00c0360-0000-4000-8000-000000000042', 0, 'Wash, peel and grate the carrots.'),
  ('c00c0360-0000-4000-8000-000000000042', 1, 'Heat the ghee in a heavy pan and saute the carrots for 5 minutes.'),
  ('c00c0360-0000-4000-8000-000000000042', 2, 'Add the milk and cook on medium heat, stirring often, until the milk is almost absorbed, 30 to 35 minutes.'),
  ('c00c0360-0000-4000-8000-000000000042', 3, 'Add the sugar. It turns runny again. Keep cooking and stirring until the halwa is thick and leaves the sides of the pan, about 10 minutes.'),
  ('c00c0360-0000-4000-8000-000000000042', 4, 'Stir in the cardamom and nuts and serve warm.');

-- Items already in pantries that link to no food may name one of the foods or
-- names above: they link the way an item added from now on does
-- (packages/db kitchen/food-link.ts) — the name itself, else without a plural
-- "es" or "s" when those agree on one food — unless their pantry answered
-- for that name (an answer wins, "none of these" included).
UPDATE kitchen_items SET food_key = COALESCE(
  (SELECT n.food_key FROM kitchen_food_names n WHERE n.name_key = lower(trim(kitchen_items.name))),
  (SELECT CASE WHEN COUNT(DISTINCT n.food_key) = 1 THEN MIN(n.food_key) END
     FROM kitchen_food_names n
     WHERE n.name_key IN (
       CASE WHEN length(lower(trim(kitchen_items.name))) > 2 AND substr(lower(trim(kitchen_items.name)), -2) = 'es'
         THEN substr(lower(trim(kitchen_items.name)), 1, length(lower(trim(kitchen_items.name))) - 2) END,
       CASE WHEN length(lower(trim(kitchen_items.name))) > 1 AND substr(lower(trim(kitchen_items.name)), -1) = 's'
         THEN substr(lower(trim(kitchen_items.name)), 1, length(lower(trim(kitchen_items.name))) - 1) END
     ))
)
WHERE food_key IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM kitchen_food_answers a
    WHERE a.owner_kind = kitchen_items.owner_kind
      AND a.owner_id = COALESCE(kitchen_items.owner_subject_id, kitchen_items.org_id)
      AND a.name_key = lower(trim(kitchen_items.name)));

-- column kitchen_foods.g_per_ml: Grams per millilitre (RC-7), so a spoon or cup of it meets a weight and a weight meets a bottle; null when it has none.
